/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create local restrict-qualified aliases with explicit leading
     dimensions.  These help the compiler optimize pointer arithmetic
     and vectorize inner loops more aggressively, while the actual
     memory layout remains exactly the same as in the original code. */
  DATA_TYPE (*restrict data_)[m] = data; /* data[n][m] */
  DATA_TYPE (*restrict cov_)[m]  = cov;  /* cov[m][m]  */
  DATA_TYPE *restrict mean_      = mean; /* mean[m]    */

#pragma scop
  /* ------------------------------------------------------------- *
   * 1. Compute column means.
   *
   * Original structure:
   *   for (j = 0; j < _PB_M; j++) {
   *     mean[j] = 0;
   *     for (i = 0; i < _PB_N; i++)
   *       mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *   }
   *
   * We split it into three phases and change the accumulation order
   * to stream `data` in row-major order (i outer, j inner):
   *
   *   1a) mean[j] = 0
   *   1b) for i, j: mean[j] += data[i][j]
   *   1c) mean[j] /= float_n
   *
   * For any fixed j, the sequence of additions forming mean[j] still
   * happens for i = 0..N-1 in increasing order; only operations on
   * *other* mean entries are interleaved differently.  Therefore, the
   * floating-point result for each mean[j] is bitwise identical to
   * the original kernel, while memory access patterns are improved.
   * ------------------------------------------------------------- */

  /* 1a. Initialize means to zero. */
  for (j = 0; j < _PB_M; j++) {
    mean_[j] = SCALAR_VAL(0.0);
  }

  /* 1b. Accumulate sums, streaming `data` row by row. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict data_i = data_[i];
    for (j = 0; j < _PB_M; j++) {
      mean_[j] += data_i[j];
    }
  }

  /* 1c. Scale by float_n (no reciprocal used, to preserve exact
         scalar-division semantics of the original code). */
  for (j = 0; j < _PB_M; j++) {
    mean_[j] /= float_n;
  }

  /* ------------------------------------------------------------- *
   * 2. Center the data in-place:
   *        data[i][j] -= mean[j];
   *
   * This loop already follows the row-major layout of `data`
   * (i outer, j inner).  We simply make pointer use explicit to
   * help optimization.
   * ------------------------------------------------------------- */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict data_i = data_[i];
    for (j = 0; j < _PB_M; j++) {
      data_i[j] -= mean_[j];
    }
  }

  /* ------------------------------------------------------------- *
   * 3. Covariance of centered data.
   *
   * Mathematical definition:
   *   cov[p][q] =
   *       1 / (float_n - 1) *
   *       sum_{k=0..N-1} data[k][p] * data[k][q]
   *   for 0 <= p, q < M, with cov symmetric: cov[q][p] = cov[p][q].
   *
   * The original implementation uses loop order (p, q, k):
   *   for p
   *     for q >= p
   *       cov[p][q] = 0;
   *       for k
   *         cov[p][q] += data[k][p] * data[k][q];
   *       cov[p][q] /= (float_n - 1);
   *       cov[q][p] = cov[p][q];
   *
   * This repeatedly scans entire columns of `data` for each (p, q).
   *
   * Below we adopt an "outer-product" style:
   *
   *   - First zero the upper triangle of `cov`.
   *   - For each centered row x = data[k][:]:
   *       for p
   *         for q >= p
   *           cov[p][q] += x[p] * x[q];
   *   - Then scale all cov[p][q] by (float_n - 1) and copy the upper
   *     triangle into the lower triangle.
   *
   * For any fixed pair (p0, q0), the updates to cov[p0][q0] still
   * occur exactly once per k, in increasing k = 0..N-1.  Only updates
   * to *other* entries are interleaved.  Thus the floating-point
   * accumulation order for each cov[p][q] is identical to that of
   * the original code, but each row of `data` is now read only once,
   * maximizing data reuse and cache locality.
   * ------------------------------------------------------------- */

  /* 3a. Initialize upper triangle of `cov` to zero. */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict cov_i = cov_[i];
    for (j = i; j < _PB_M; j++) {
      cov_i[j] = SCALAR_VAL(0.0);
    }
  }

  /* 3b. Accumulate unscaled covariance via outer products. */
  for (k = 0; k < _PB_N; k++) {
    DATA_TYPE *restrict row = data_[k];

    for (i = 0; i < _PB_M; i++) {
      DATA_TYPE xi = row[i];
      DATA_TYPE *restrict cov_i = cov_[i];

      /* Inner loop touches cov_i[j] and row[j] contiguously in j,
         which is friendly to both caches and auto-vectorization. */
      for (j = i; j < _PB_M; j++) {
        cov_i[j] += xi * row[j];
      }
    }
  }

  /* 3c. Scale the upper triangle by (float_n - 1.0). */
  const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict cov_i = cov_[i];
    for (j = i; j < _PB_M; j++) {
      cov_i[j] /= denom;
    }
  }

  /* 3d. Symmetrize: copy upper triangle into lower triangle. */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict cov_i = cov_[i];
    for (j = i + 1; j < _PB_M; j++) {
      cov_[j][i] = cov_i[j];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
