/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create local restrict-qualified aliases to help the compiler
     optimize memory accesses. PolyBench allocates these arrays in
     separate contiguous regions, so this assumption holds. */
  DATA_TYPE (*restrict data_)[m] = data;
  DATA_TYPE (*restrict cov_)[m]  = cov;
  DATA_TYPE *restrict mean_      = mean;

  /* Hoist reciprocals of float_n and (float_n - 1.0) out of the loops.
     Using multiplication instead of repeated division reduces the cost
     of the scaling steps. This is mathematically equivalent, with only
     negligible differences in final rounding. */
  const DATA_TYPE inv_float_n =
    SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE inv_float_n_minus1 =
    SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));

#pragma scop
