     Original code iterated column-major (j outer, i inner), which causes
     strided accesses to row-major data. Here we:
       - initialize mean[j] to 0 in a separate pass,
       - accumulate using row-major order (i outer, j inner),
       - then scale by 1/float_n.
     For each column j, the sequence of additions over i remains in the
     same order (i = 0.._PB_N-1), so the per-column sums are unchanged;
     only operations on different columns are interleaved. */

  /* Initialization: mean[j] = 0. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulation: stream 'data' row-major (i outer, j inner). */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; j++)
        mean_[j] += data_row[j];
    }

  /* Scaling: mean[j] /= float_n, implemented as multiplication by its reciprocal. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] *= inv_float_n;

  /* 2. Center the data matrix in-place:
       data[i][j] <- data[i][j] - mean[j]
     This already traverses 'data' in row-major order.
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict data_row = data_[i];
      for (j = 0; j < _PB_M; j++)
        data_row[j] -= mean_[j];
    }

