     Mathematical definition:
       cov[i][j] = 1 / (float_n - 1) *
                   sum_{k=0..N-1} data[k][i] * data[k][j]

     We exploit symmetry (cov[j][i] == cov[i][j]) and compute only the
     upper triangle (j >= i), then mirror.

     To improve locality, we:
       - first initialize the upper triangle to zero,
       - then, for each observation (row k), perform an outer-product-
         style update of cov using that row.
     For any fixed pair (i0, j0), the contributions to cov[i0][j0]
     are accumulated in increasing order of k (0.._PB_N-1), exactly
     as in the original code; updates to different matrix elements
     are simply interleaved. */

  /* 3a. Initialize upper triangle of cov to zero. */
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      cov_[i][j] = SCALAR_VAL(0.0);

  /* 3b. Accumulate unscaled covariance: outer-product formulation. */
  for (k = 0; k < _PB_N; k++)
    {
      DATA_TYPE *restrict data_row = data_[k];

      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE data_i = data_row[i];

          for (j = i; j < _PB_M; j++)
            cov_[i][j] += data_i * data_row[j];
        }
    }

  /* 3c. Scale by 1/(float_n - 1) and symmetrize the matrix. */
  for (i = 0; i < _PB_M; i++)
    {
      for (j = i; j < _PB_M; j++)
        {
          cov_[i][j] *= inv_float_n_minus1;
          cov_[j][i] = cov_[i][j];
        }
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

