   * 2. Center the data: data[i][j] -= mean[j]
   *    (unchanged mathematically; still row-major).
   * -------------------------------------------------------- */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *row = data[i];
#pragma GCC ivdep
    for (j = 0; j < _PB_M; j++)
      row[j] -= mean[j];
  }

