   *    are accumulated in increasing k order, as in the original.
   * -------------------------------------------------------- */

  /* 3a. Initialize upper triangle of cov to 0.0, blocked. */
  for (ii = 0; ii < _PB_M; ii += TILE_M)
  {
    int i_max = ii + TILE_M;
    if (i_max > _PB_M)
      i_max = _PB_M;

    /* Only iterate tiles in the upper triangle: jj starts at ii. */
    for (jj = ii; jj < _PB_M; jj += TILE_M)
    {
      int j_max = jj + TILE_M;
      if (j_max > _PB_M)
        j_max = _PB_M;

      for (i = ii; i < i_max; i++)
      {
        /* Within this tile, start j at max(i, jj) to enforce j >= i. */
        int j_start = (i > jj) ? i : jj;
